package com.lootingbagviewer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LootingBagViewerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LootingBagViewerPlugin.class);
		RuneLite.main(args);
	}
}

package com.lootingbagviewer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LootingBagViewerConfig.GROUP)
public interface LootingBagViewerConfig extends Config
{
	String GROUP = "lootingbagviewer";

	@ConfigItem(
		keyName = "showOnTop",
		name = "Show above other tooltips",
		description = "Show the bag contents right below the hover text, above tooltips from other plugins",
		position = 1
	)
	default boolean showOnTop()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPrices",
		name = "Show total value",
		description = "Show the total Grand Exchange value of the bag below the icons",
		position = 2
	)
	default boolean showPrices()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHighAlch",
		name = "Show high alch value",
		description = "Show the total high alchemy value of the bag below the icons",
		position = 3
	)
	default boolean showHighAlch()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sortByValue",
		name = "Sort by value",
		description = "List the most valuable stacks first instead of in bag order",
		position = 4
	)
	default boolean sortByValue()
	{
		return false;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "The color of the value text below the icons",
		position = 5
	)
	default Color textColor()
	{
		return Color.WHITE;
	}
}

package com.lootingbagviewer;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Looting Bag Viewer",
	description = "Shows the contents of your looting bag when you hover over it",
	tags = {"looting", "bag", "wilderness", "pvp", "tooltip", "loot"}
)
public class LootingBagViewerPlugin extends Plugin
{
	private static final String CONTENTS_KEY = "contents";
	private static final int BAG_SIZE = 28;

	// How long to wait for a deposit to land before giving up on it
	private static final int USE_TIMEOUT_TICKS = 100;
	private static final int PICKUP_TIMEOUT_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private LootingBagViewerOverlay overlay;

	/**
	 * Last known bag contents, or null if the bag has never been checked on this account.
	 * The server only sends the looting bag inventory when the bag is checked, so deposits
	 * are tracked locally and contents are persisted per account to survive relogs.
	 */
	@Getter(AccessLevel.PACKAGE)
	private List<Item> contents;

	private Map<Integer, Integer> lastInventory = new HashMap<>();

	@Getter(AccessLevel.PACKAGE)
	private boolean bagInInventory;

	// Tick the bag's own window was opened, so its contents can be read once they load
	private int bagViewedTick = -1;

	// Item used on the bag, waiting for it to leave the inventory (the "How many?" dialog can sit open)
	private int pendingUseItemId = -1;
	private int pendingUseTick;

	// Item clicked on the ground while the bag is open, waiting to see where it ends up
	private PendingPickup pendingPickup;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadContents();
				updateInventory(countItems(client.getItemContainer(InventoryID.INV)));
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		contents = null;
		updateInventory(new HashMap<>());
		clearPending();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Tick counts restart on login, so anything still pending would never time out
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			clearPending();
		}

		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			updateInventory(new HashMap<>());
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadContents();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.LOOTING_BAG)
		{
			syncFromContainer(event.getItemContainer());
		}
		else if (event.getContainerId() == InventoryID.INV)
		{
			Map<Integer, Integer> inventory = countItems(event.getItemContainer());

			if (pendingUseItemId != -1)
			{
				int removed = lastInventory.getOrDefault(pendingUseItemId, 0) - inventory.getOrDefault(pendingUseItemId, 0);
				if (removed > 0)
				{
					log.debug("Deposited {} x {} by using it on the bag", removed, pendingUseItemId);
					addToBag(pendingUseItemId, removed);
					pendingUseItemId = -1;
				}
			}

			updateInventory(inventory);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.WILDERNESS_LOOTINGBAG)
		{
			bagViewedTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.WILDERNESS_LOOTINGBAG)
		{
			bagViewedTick = -1;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();

		// Picking an amount in the "How many?" dialog continues the deposit
		if (action == MenuAction.WIDGET_CONTINUE)
		{
			return;
		}

		// Any other click means the player moved on from a deposit that never happened
		pendingUseItemId = -1;

		if (action == MenuAction.WIDGET_TARGET_ON_WIDGET)
		{
			Widget selected = client.getSelectedWidget();
			Widget target = event.getWidget();
			if (selected == null || target == null)
			{
				return;
			}

			// Works both ways round: item on bag, or bag on item. Spells cast on the bag have no item id
			int selectedId = selected.getItemId();
			int targetId = target.getItemId();
			int depositId = isLootingBag(targetId) ? selectedId : isLootingBag(selectedId) ? targetId : -1;
			if (depositId > 0 && !isLootingBag(depositId))
			{
				pendingUseItemId = depositId;
				pendingUseTick = client.getTickCount();
			}
			return;
		}

		if (!isGroundItemAction(action) || !"Take".equals(event.getMenuOption()) || !isBagOpen())
		{
			return;
		}

		WorldView worldView = client.getWorldView(event.getMenuEntry().getWorldViewId());
		if (worldView == null)
		{
			return;
		}

		int itemId = event.getId();
		pendingPickup = new PendingPickup(
			itemId,
			WorldPoint.fromScene(worldView, event.getParam0(), event.getParam1(), worldView.getPlane()),
			client.getTickCount(),
			lastInventory.getOrDefault(itemId, 0));
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		PendingPickup pickup = pendingPickup;
		if (pickup == null || pickup.despawnTick != -1 || event.getItem().getId() != pickup.itemId)
		{
			return;
		}

		WorldPoint location = event.getTile().getWorldLocation();
		if (!location.equals(pickup.location))
		{
			return;
		}

		// Only count it if we're the one standing on the item, not someone else taking it
		Player player = client.getLocalPlayer();
		if (player == null || !player.getWorldLocation().equals(location))
		{
			return;
		}

		pickup.quantity = event.getItem().getQuantity();
		pickup.despawnTick = client.getTickCount();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();

		// An empty bag sends no container update when checked, so read it once the window has loaded
		if (bagViewedTick != -1 && tick > bagViewedTick)
		{
			bagViewedTick = -1;
			syncFromContainer(client.getItemContainer(InventoryID.LOOTING_BAG));
		}

		if (pendingUseItemId != -1 && tick - pendingUseTick > USE_TIMEOUT_TICKS)
		{
			pendingUseItemId = -1;
		}

		PendingPickup pickup = pendingPickup;
		if (pickup == null)
		{
			return;
		}

		if (pickup.despawnTick == -1)
		{
			if (tick - pickup.clickTick > PICKUP_TIMEOUT_TICKS)
			{
				pendingPickup = null;
			}
			return;
		}

		// Give the inventory a tick to update. If the item didn't show up there, it went in the bag
		// (with the "supplies go to inventory" setting, food and potions land in the inventory instead)
		if (tick > pickup.despawnTick)
		{
			int gained = lastInventory.getOrDefault(pickup.itemId, 0) - pickup.inventoryCountBefore;
			if (gained <= 0 && isBagOpen())
			{
				log.debug("Picked up {} x {} into the bag", pickup.quantity, pickup.itemId);
				addToBag(pickup.itemId, pickup.quantity);
			}
			pendingPickup = null;
		}
	}

	/**
	 * Replaces the tracked contents with the real ones from the server. A null container means an empty bag.
	 */
	private void syncFromContainer(ItemContainer container)
	{
		List<Item> items = new ArrayList<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0)
				{
					items.add(item);
				}
			}
		}
		setContents(items);
	}

	private void addToBag(int itemId, int quantity)
	{
		// Without a baseline from checking the bag, a partial list would be misleading
		if (contents == null || itemId <= 0 || quantity <= 0)
		{
			return;
		}

		List<Item> items = new ArrayList<>(contents);
		if (itemManager.getItemComposition(itemId).isStackable())
		{
			boolean merged = false;
			for (int i = 0; i < items.size(); i++)
			{
				Item item = items.get(i);
				if (item.getId() == itemId)
				{
					int total = (int) Math.min((long) item.getQuantity() + quantity, Integer.MAX_VALUE);
					items.set(i, new Item(itemId, total));
					merged = true;
					break;
				}
			}

			if (!merged && items.size() < BAG_SIZE)
			{
				items.add(new Item(itemId, quantity));
			}
		}
		else
		{
			for (int i = 0; i < quantity && items.size() < BAG_SIZE; i++)
			{
				items.add(new Item(itemId, 1));
			}
		}

		setContents(items);
	}

	private void setContents(List<Item> items)
	{
		// Checking the bag can report the same contents twice (container update, then the window sync)
		if (items.equals(contents))
		{
			return;
		}

		contents = Collections.unmodifiableList(items);
		overlay.invalidate();
		saveContents();
	}

	private void updateInventory(Map<Integer, Integer> inventory)
	{
		lastInventory = inventory;
		bagInInventory = inventory.containsKey(ItemID.LOOTING_BAG) || isBagOpen();
	}

	private boolean isBagOpen()
	{
		return lastInventory.containsKey(ItemID.LOOTING_BAG_OPEN);
	}

	private void clearPending()
	{
		pendingUseItemId = -1;
		pendingPickup = null;
		bagViewedTick = -1;
	}

	private static boolean isLootingBag(int itemId)
	{
		return itemId == ItemID.LOOTING_BAG || itemId == ItemID.LOOTING_BAG_OPEN;
	}

	private static boolean isGroundItemAction(MenuAction action)
	{
		switch (action)
		{
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	private static Map<Integer, Integer> countItems(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0)
				{
					counts.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return counts;
	}

	private void loadContents()
	{
		contents = parse(configManager.getRSProfileConfiguration(LootingBagViewerConfig.GROUP, CONTENTS_KEY));
		overlay.invalidate();
	}

	private void saveContents()
	{
		StringBuilder sb = new StringBuilder();
		for (Item item : contents)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(item.getId()).append(':').append(item.getQuantity());
		}
		configManager.setRSProfileConfiguration(LootingBagViewerConfig.GROUP, CONTENTS_KEY, sb.toString());
	}

	private static List<Item> parse(String value)
	{
		if (value == null)
		{
			return null;
		}

		List<Item> items = new ArrayList<>();
		for (String entry : value.split(","))
		{
			String[] parts = entry.split(":");
			if (parts.length != 2)
			{
				continue;
			}

			try
			{
				items.add(new Item(Integer.parseInt(parts[0]), Integer.parseInt(parts[1])));
			}
			catch (NumberFormatException e)
			{
				log.debug("Skipping malformed looting bag entry {}", entry);
			}
		}
		return Collections.unmodifiableList(items);
	}

	private static final class PendingPickup
	{
		final int itemId;
		final WorldPoint location;
		final int clickTick;
		final int inventoryCountBefore;
		int quantity;
		int despawnTick = -1;

		PendingPickup(int itemId, WorldPoint location, int clickTick, int inventoryCountBefore)
		{
			this.itemId = itemId;
			this.location = location;
			this.clickTick = clickTick;
			this.inventoryCountBefore = inventoryCountBefore;
		}
	}

	@Provides
	LootingBagViewerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LootingBagViewerConfig.class);
	}
}

package com.lootingbagviewer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

class LootingBagViewerOverlay extends Overlay
{
	private static final Color HINT_COLOR = Color.LIGHT_GRAY;
	private static final int PANEL_BORDER = 4;
	private static final int ICON_GAP = 6;
	private static final int MAX_COLUMNS = 4;

	private final Client client;
	private final LootingBagViewerPlugin plugin;
	private final LootingBagViewerConfig config;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;
	private final RuneLiteConfig runeLiteConfig;

	private final PanelComponent panel = new PanelComponent();
	private final PanelComponent grid = new PanelComponent();
	private final Tooltip tooltip = new Tooltip(panel);
	private boolean hovering;
	private boolean dirty = true;

	@Inject
	LootingBagViewerOverlay(Client client, LootingBagViewerPlugin plugin, LootingBagViewerConfig config,
		ItemManager itemManager, TooltipManager tooltipManager, RuneLiteConfig runeLiteConfig)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.runeLiteConfig = runeLiteConfig;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);

		// Inventory-style grid, 4 icons per row
		grid.setBackgroundColor(null);
		grid.setBorder(new Rectangle());
		grid.setWrap(true);
		grid.setOrientation(ComponentOrientation.HORIZONTAL);
		grid.setGap(new Point(ICON_GAP, ICON_GAP));

		panel.setBorder(new Rectangle(PANEL_BORDER, PANEL_BORDER, PANEL_BORDER, PANEL_BORDER));
	}

	void invalidate()
	{
		dirty = true;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!isHoveringLootingBag())
		{
			hovering = false;
			return null;
		}

		// Rebuild when the hover starts so prices and config changes are picked up,
		// without doing the work every frame while the mouse rests on the bag
		if (!hovering || dirty)
		{
			rebuild(graphics);
			hovering = true;
			dirty = false;
		}

		if (config.showOnTop())
		{
			// This overlay renders before Mouse Highlighting, which also adds to the front,
			// so the contents sit right below the "Close Looting bag" text instead of under other plugins' tooltips
			tooltipManager.addFront(tooltip);
		}
		else
		{
			tooltipManager.add(tooltip);
		}
		return null;
	}

	private boolean isHoveringLootingBag()
	{
		// Runs every frame, so bail out cheaply for the common case of not carrying a bag.
		// The bag's own interface already shows its contents, so stay out of the way while it's open
		if (!plugin.isBagInInventory() || client.isMenuOpen() || isLootingBagInterfaceOpen())
		{
			return false;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return false;
		}

		// Only item widgets (inventory, bank side inventory, etc.), not a bag lying on the ground
		Widget widget = entries[entries.length - 1].getWidget();
		if (widget == null)
		{
			return false;
		}

		int itemId = widget.getItemId();
		return itemId == ItemID.LOOTING_BAG || itemId == ItemID.LOOTING_BAG_OPEN;
	}

	private boolean isLootingBagInterfaceOpen()
	{
		Widget bagInterface = client.getWidget(InterfaceID.WildernessLootingbag.UNIVERSE);
		return bagInterface != null && !bagInterface.isHidden();
	}

	private void rebuild(Graphics2D graphics)
	{
		panel.getChildren().clear();

		List<Item> contents = plugin.getContents();
		if (contents == null)
		{
			addHint(graphics, "Check");
			return;
		}

		if (contents.isEmpty())
		{
			addHint(graphics, "Empty");
			return;
		}

		List<Stack> stacks = new ArrayList<>(contents.size());
		long total = 0;
		long alchTotal = 0;
		for (Item item : contents)
		{
			ItemComposition composition = itemManager.getItemComposition(item.getId());
			long value = (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
			stacks.add(new Stack(item, value, composition.isStackable()));
			total += value;
			alchTotal += (long) composition.getHaPrice() * item.getQuantity();
		}

		if (config.sortByValue())
		{
			stacks.sort(Comparator.comparingLong((Stack s) -> s.value).reversed());
		}

		// Size the grid to the items, up to 4 per row like the inventory
		int columns = Math.min(stacks.size(), MAX_COLUMNS);
		int gridWidth = columns * Constants.ITEM_SPRITE_WIDTH + (columns - 1) * ICON_GAP;
		grid.setPreferredSize(new Dimension(gridWidth, 0));

		// Label the totals only when both are shown, so a single total stays as compact as before
		boolean showPrices = config.showPrices();
		boolean showHighAlch = config.showHighAlch();
		boolean labelled = showPrices && showHighAlch;
		List<String> totals = new ArrayList<>(2);
		if (showPrices)
		{
			totals.add((labelled ? "GE: " : "") + QuantityFormatter.quantityToStackSize(total) + " gp");
		}
		if (showHighAlch)
		{
			totals.add("HA: " + QuantityFormatter.quantityToStackSize(alchTotal) + " gp");
		}

		int contentWidth = gridWidth;
		for (String text : totals)
		{
			contentWidth = Math.max(contentWidth, textWidth(graphics, text));
		}
		setPanelWidth(contentWidth);

		grid.getChildren().clear();
		for (Stack stack : stacks)
		{
			Item item = stack.item;
			grid.getChildren().add(new ImageComponent(itemManager.getImage(item.getId(), item.getQuantity(), stack.stackable)));
		}
		panel.getChildren().add(grid);

		for (String text : totals)
		{
			panel.getChildren().add(LineComponent.builder()
				.left(text)
				.leftColor(config.textColor())
				.build());
		}
	}

	private void addHint(Graphics2D graphics, String text)
	{
		// Fit short hints snugly; longer ones wrap at the width of a full row of icons
		int fullRowWidth = MAX_COLUMNS * Constants.ITEM_SPRITE_WIDTH + (MAX_COLUMNS - 1) * ICON_GAP;
		setPanelWidth(Math.min(textWidth(graphics, text), fullRowWidth));
		panel.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(HINT_COLOR)
			.build());
	}

	private int textWidth(Graphics2D graphics, String text)
	{
		// Tooltips are drawn with the user's tooltip font, not the font this overlay renders with.
		// A little slack so the text never wraps onto a second line
		return graphics.getFontMetrics(runeLiteConfig.tooltipFont().getFont()).stringWidth(text) + 4;
	}

	private void setPanelWidth(int contentWidth)
	{
		panel.setPreferredSize(new Dimension(contentWidth + 2 * PANEL_BORDER, 0));
	}

	private static final class Stack
	{
		final Item item;
		final long value;
		final boolean stackable;

		Stack(Item item, long value, boolean stackable)
		{
			this.item = item;
			this.value = value;
			this.stackable = stackable;
		}
	}
}
